cs={c['capture_id']:c for c in m['captures']}
def evidence(ids):
 out=[]
 for cid in ids:
  c=cs[cid]; f=p/c['screenshot'];out.append(f'- {cid} / {c["id"]}: [{f}]({f}). Package-relative path: `{c["screenshot"]}`.')
 return '\n'.join(out)
def finding(fid,title,kind,priority,confidence,surface,ids,app,obs,why,rec,criteria,extra):
 return f'''\n## {fid} — {title}\n\nClassification: **{kind}**. Priority: **{priority}**. Confidence: **{confidence}**.\n\nAffected surface/state: {surface}\n\nRuntime/build applicability: {app}\n\n{evidence(ids)}\n\nVisible evidence: {obs}\n\nUser consequence: {why}\n\nRecommendation: {rec}\n\nAcceptance criteria: {criteria}\n\nAdditional evidence: {extra}\n'''
